package app.quanneng;
import android.content.*;
import android.database.Cursor;
import android.graphics.*;
import android.media.MediaMetadataRetriever;
import android.net.Uri;
import android.os.Bundle;
import android.provider.*;
import android.widget.*;
import java.io.*;
import java.util.*;
/** 仅扫描用户授权的目录，逐页生成本地封面，不上传媒体。 */
public final class LibraryActivity extends FeatureActivity {
 static final class Item {Uri uri;String name;long size,modified;Item(Uri u,String n,long s,long m){uri=u;name=n;size=s;modified=m;}}
 private final List<Item> items=new ArrayList<>();private LinearLayout wall;private EditText search;private boolean newest=true;private int shown;private int epoch;
 static String name(Context c,Uri u){try(Cursor x=c.getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(x!=null&&x.moveToFirst())return x.getString(0);}catch(Exception ignored){}return u.getLastPathSegment()==null?"视频":u.getLastPathSegment();}
 @Override public void onCreate(Bundle b){super.onCreate(b);page("本地影音海报墙");text(body,"选择一个视频目录。可打开系统文件提供器中的 NAS / SMB 目录。",14);button(body,"选择 / 更换媒体目录",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),92));search=input("搜索文件名","");search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){render();}public void afterTextChanged(android.text.Editable e){}});button(body,"切换排序：名称 / 最新",()->{newest=!newest;render();});wall=new LinearLayout(this);wall.setOrientation(1);body.addView(wall);button(body,"加载更多",this::more);whenUnlocked(this::scan);}
 private void scan(){String saved=getPreferences(0).getString("tree","");work("读取已授权媒体…",()->{List<Item> found=new ArrayList<>();if(!saved.isEmpty())walk(Uri.parse(saved),DocumentsContract.getTreeDocumentId(Uri.parse(saved)),found,0);for(File f:TransferService.completed(this))if(!f.getName().endsWith(".jpg"))found.add(new Item(MediaContentProvider.uri(f),f.getName(),f.length(),f.lastModified()));return found;},list->{items.clear();items.addAll(list);message.setText("找到 "+items.size()+" 个文件（单次最多 2000 个）");render();});}
 private void walk(Uri tree,String id,List<Item> out,int depth)throws Exception{if(depth>8||out.size()>=2000)return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED},null,null,null)){if(c==null)return;List<String> dirs=new ArrayList<>();while(c.moveToNext()&&out.size()<2000){if(Thread.currentThread().isInterrupted())throw new IOException();if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))dirs.add(c.getString(0));else if(c.getString(2).startsWith("video/")||c.getString(1).matches("(?i).*\\.(mp4|mkv|webm|mov|m4v|avi)$"))out.add(new Item(DocumentsContract.buildDocumentUriUsingTree(tree,c.getString(0)),c.getString(1),c.getLong(3),c.getLong(4)));}for(String dir:dirs)walk(tree,dir,out,depth+1);}}
 private void render(){if(wall==null)return;epoch++;wall.removeAllViews();shown=0;items.sort(newest?(a,b)->Long.compare(b.modified,a.modified):Comparator.comparing(a->a.name.toLowerCase(Locale.ROOT)));more();}
 private void more(){if(wall==null)return;String q=search.getText().toString().toLowerCase(Locale.ROOT);int added=0;while(shown<items.size()&&added<24){Item item=items.get(shown++);if(!item.name.toLowerCase(Locale.ROOT).contains(q))continue;added++;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(0,dp(12),0,dp(12));wall.addView(card);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setContentDescription(item.name+"的视频封面");image.setBackgroundColor(PlayerUi.SURFACE);card.addView(image,new LinearLayout.LayoutParams(-1,dp(160)));text(card,item.name+String.format(Locale.ROOT," · %.1f MB",item.size/1048576.0),16);button(card,"播放",()->play(item.uri));final int batch=epoch;io.execute(()->{MediaMetadataRetriever m=new MediaMetadataRetriever();try{if(!PrivateSession.isUnlocked())return;m.setDataSource(this,item.uri);Bitmap bitmap=m.getScaledFrameAtTime(1000000,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,480,270);runOnUiThread(()->{if(epoch==batch&&!isDestroyed()&&bitmap!=null)image.setImageBitmap(bitmap);else if(bitmap!=null)bitmap.recycle();});}catch(Exception ignored){}finally{try{m.release();}catch(Exception ignored){}}});}if(wall.getChildCount()==0)text(wall,"没有匹配的视频。请选择目录或先下载视频。",14);}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==92&&result==RESULT_OK&&data!=null&&data.getData()!=null)whenUnlocked(()->{Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);getPreferences(0).edit().putString("tree",u.toString()).apply();scan();}catch(SecurityException e){message.setText("未取得目录授权，请重新选择");}});}
}
